<script>
import BaseComponent from '@primevue/core/basecomponent';
import GalleryItemStyle from 'primevue/galleryitem/style';

export default {
    name: 'BaseGalleryItem',
    extends: BaseComponent,
    props: {
        normalScale: {
            type: Number,
            default: 1
        },
        zoomedScale: {
            type: Number,
            default: 3
        },
        as: {
            type: [String, Object],
            default: 'DIV'
        },
        asChild: {
            type: Boolean,
            default: false
        }
    },
    style: GalleryItemStyle,
    provide() {
        return {
            $pcGalleryItem: this,
            $parentInstance: this
        };
    }
};
</script>
